head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
scwin.vScrenID = "ULDSTF20509.xml";
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gMajContCdIndex = 100;
scwin.isFileDelete = false;
scwin.vJobMode = "";
scwin.vBZ_PROCS_NO = "";
scwin.trsIdx = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init_code = function() {
    var arrCid = [{
        cid: "REAL_INVSTG_STEP_CD",
        cnm: "cmb_REAL_INVSTG_STEP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='REAL_INVSTG_STEP_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    var strCbd = "",
        i, j;
    var strGubun = "";
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Code.getTotalRow(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strGubun = dts_Code.getCellData(j, "VALUE").substring(0, 1); //코 1XX, 유 2XX
                if (scwin.gLdMktTp == strGubun) {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
                } else if (scwin.gLdMktTp == '9') {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_init_ctrl = function() {
    if (scwin.gLdMktTp == "1") {
        $c.stf.showObj(lbl_stat_23, false);
        $c.stf.showObj(lbl_stat_13, true);
        scwin.gMajContCdIndex = 100; // 유가  1XX

    } else {
        $c.stf.showObj(lbl_stat_23, true);
        $c.stf.showObj(lbl_stat_13, false);
        scwin.gMajContCdIndex = 200; // 코스닥 2XX

    }
    if (scwin.vJobMode == 'M') {
        getBZ_PROCS_NO = $c.frame.path("../").fn_getBZ_PROCS_NO;
        scwin.vBZ_PROCS_NO = getBZ_PROCS_NO();
        btn_Delete.setDisabled(false);
        btn_Delete.src = "../img/btn_delete.gif";
        $c.stf.showObj(img_com_srch, false);
        scwin.fn_list_sync();
    } else {
        scwin.fn_setFileDataHeader();
        scwin.fn_SetSaveHeader();
        btn_Delete.setDisabled(true);
        btn_Delete.src = "../img/btn_delete_d.gif";
    }
};
scwin.fn_chk_form = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("'회사코드(명)'을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_TITLE) == "") {
        $c.win.alert("'제목'을 입력하세요.");
        return false;
    }
    return true;
};
scwin.fn_pre_build = function() {
    $c.stf.CopyDataSet(dts_REAL_INVSTG_DATA, dts_REAL_INVSTG_DATA1);
    for (var i = 1; i <= 4; i++) {
        if (dts_REAL_INVSTG_DATA.getCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i) == "1") {
            if (i == 4) dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, scwin.gMajContCdIndex + 99);

            else dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, scwin.gMajContCdIndex + i);
        } else dts_REAL_INVSTG_DATA1.setCellData(1, "REAL_INVSTG_MAJ_CONTN_CD" + i, "");
    }
    if ($c.cp.isModified(dts_fileList)) {
        scwin.isFileDelete = true;
    }
};
scwin.fn_chk_chrg = function() {
    if (js_usr_tp_cd == '1') {
        //운영자이면
        return true;
    }
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=REAL_INVSTG_DATA_CHRG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.real_invstg_data.chrg" + "&{P}param01=" + js_emp_no + "&{P}param02=" + js_emp_no + "&{P}param03=" + js_emp_no + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_Chrg.DataID = encodeURI(url);
    dts_Chrg.Reset();
    var chrgYn = dts_Chrg.getCellData(1, "CHRG_YN");
    if (chrgYn != 'Y') {
        $c.win.alert("해당종목 담당자와 담당 팀장만 변경 가능합니다.");
        return false;
    }
    return true;
};
scwin.fn_list_sync = function() {
    trs_Read.Action = "/RealInvstg.do?method=getRealInvstgData" + "&BZ_PROCS_NO=" + scwin.vBZ_PROCS_NO + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_REAL_INVSTG_DATA, O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_chk_form() == false) return;
    if (scwin.fn_chk_chrg() == false) return;
    if (dts_fileList.getCellData(1, "fileInfo") == "") {
        dts_fileList.Reset();
    }
    var rtn = confirm('저장 하시겠습니까?');
    if (rtn == 1) {
        scwin.trsIdx = TRS_IDX_INSERT;
        scwin.fn_pre_build();
        scwin.vBZ_PROCS_NO = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        dts_REAL_INVSTG_DATA1.setCellData(1, "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
        trs_Save.Action = $c.lc.fn_encodeNSession("/RealInvstg.do?method=insertInvstgData" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02);
        trs_Save.KeyValue = "JSP(I:pInput=dts_REAL_INVSTG_DATA1,I:pFile=dts_fileList)";
        trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",COUNT=0" + ",BZ_PROCS_NO=" + scwin.vBZ_PROCS_NO + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_207 + ",LD_MKT_TP_CD=" + scwin.gLdMktTp + ",ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    if (scwin.fn_chk_form() == false) return;
    if (scwin.fn_chk_chrg() == false) return;
    var rtn = confirm('수정 하시겠습니까?');
    if (rtn == 1) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        scwin.fn_pre_build();
        trs_Update.Action = $c.lc.fn_encodeNSession("/RealInvstg.do?method=updateInvstgData&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Update.KeyValue = "JSP(I:pInput=dts_REAL_INVSTG_DATA1,I:pFile=dts_fileList)";
        trs_Update.Parameters = "TRS_IDX=" + scwin.trsIdx + ",COUNT=0" + ",BZ_PROCS_NO=" + scwin.vBZ_PROCS_NO + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_207 + ",LD_MKT_TP_CD=" + scwin.gLdMktTp + ",ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    if (scwin.fn_chk_chrg() == false) return;
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {
        scwin.trsIdx = TRS_IDX_DELETE;
        scwin.fn_pre_build();
        trs_Delete.Action = $c.lc.fn_encodeNSession("/RealInvstg.do?method=deleteInvstgData&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04);
        trs_Delete.KeyValue = "JSP(I:pInput=dts_REAL_INVSTG_DATA1)";
        trs_Delete.Parameters = "TRS_IDX=" + scwin.trsIdx + ",COUNT=0" + ",BZ_PROCS_NO=" + scwin.vBZ_PROCS_NO;
        ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_207 + ",LD_MKT_TP_CD=" + scwin.gLdMktTp + ",ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
        trs_Delete.Post();
    }
};
scwin.fn_setFileDataHeader = function() {
    dts_fileList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=REAL_INVSTG_DATA_ATTACH_INOUT";
    dts_fileList.Reset();
};
scwin.fn_SetSaveHeader = function() {
    dts_REAL_INVSTG_DATA.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=REAL_INVSTG_DATA";
    dts_REAL_INVSTG_DATA.Reset();
    dts_REAL_INVSTG_DATA.insertRow();
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD1", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD2", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD3", "0");
    dts_REAL_INVSTG_DATA.setCellData(dts_REAL_INVSTG_DATA.getRowPosition(), "REAL_INVSTG_MAJ_CONTN_CD4", "0");
};
scwin.fn_filedown = function() {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO") + "&SEQ=" + dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") + "&gubun=48";
};
scwin.callElasticFileNoti = function() {
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiElasticCommon",
            P_bzProcsNo: scwin.vBZ_PROCS_NO,
            url: "/index/tbld_real_invstg_data_file/kafka",
            type: "POST"
        },
        async: true
    });
    scwin.isFileDelete = false;
};
scwin.fn_setButton = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=BYCORP_DEP_CD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.bycorpdepcd.condition" + "&{P}param01=" + isurCd;
    param_Dts.DataID = encodeURI(url);
    param_Dts.Reset();
    var depCd = param_Dts.getCellData(1, "DEP_CD");
    if (jsDepCd != depCd) {

    }
};
scwin.btn_Save_onclick = function() {
    if (scwin.vJobMode == "M") {
        scwin.fn_update();
    } else {
        scwin.fn_save();
    }
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.isFileDelete) scwin.callElasticFileNoti();
    $c.frame.path("../").fn_list_sync();
    dts_REAL_INVSTG_DATA.setCellData(1, "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
    scwin.vJobMode = "M";
    btn_Delete.setDisabled(false);
    btn_Delete.src = "../img/btn_delete.gif";
    scwin.fn_list_sync();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = function() {
    if (scwin.isFileDelete) scwin.callElasticFileNoti();
    $c.frame.path("../").fn_list_sync();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    scwin.fn_list_sync();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    scwin.callElasticFileNoti();
    $c.frame.path("../").fn_list_sync();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.dts_REAL_INVSTG_DATA_OnLoadError = function() {
    $c.win.alert('dts_REAL_INVSTG_DATA.OnLoadError()');
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    if (scwin.vJobMode == "I") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.vJobMode == "I") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            var seq = dts_fileList.getRowPosition();
            for (i = 0; i < dts_fileList.getTotalRow(); i++) {
                if (dts_fileList.getCellData(i, "ATTACH_SEQ") == seq) {
                    seq++;
                    i = 0;
                }
            }
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", seq);
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "BZ_PROCS_NO", scwin.vBZ_PROCS_NO);
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    if (dts_fileList.getCellData(dts_fileList.getRowPosition(), "USR_TP_CD") == "3") $c.win.alert("상장법인이 제출한 첨부파일은 삭제되지 않습니다.");

    else $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0 && dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename") != "" && dts_fileList.getCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ") != "") {
        $c.elw.fn_filedown();
    }
};
scwin.grd_fileList_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_init_code();
    scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
    scwin.fn_init_ctrl();
};
